import { Component, OnInit } from '@angular/core';
import { WishlistItem } from '../../models/product.model';
import { ProductService } from '../../services/product.service';
import { CartService } from '../../services/cart.service';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-wishlist',
  templateUrl: './wishlist.component.html',
  styleUrls: ['./wishlist.component.css']
})
export class WishlistComponent implements OnInit {
  wishlistItems: WishlistItem[] = [];
  searchQuery: string = '';
  filteredItems: WishlistItem[] = [];

  constructor(
    private productService: ProductService,
    private cartService: CartService,
    private authService: AuthService
  ) {}

  ngOnInit(): void {
    this.loadWishlist();
  }

  loadWishlist(): void {
    const user = this.authService.getCurrentUser();
    if (user) {
      const wishlistKey = `wishlist_${user.id}`;
      const wishlistData = localStorage.getItem(wishlistKey);
      this.wishlistItems = wishlistData ? JSON.parse(wishlistData) : [];
      this.filteredItems = [...this.wishlistItems];
    }
  }

  onSearch(): void {
    if (this.searchQuery.trim()) {
      this.filteredItems = this.wishlistItems.filter(item =>
        item.name.toLowerCase().includes(this.searchQuery.toLowerCase())
      );
    } else {
      this.filteredItems = [...this.wishlistItems];
    }
  }

  addToCart(item: WishlistItem): void {
    const product = this.productService.getProductById(item.productId);
    if (product) {
      this.cartService.addToCart(product);
      this.showToast(`${item.name} added to cart`, 'success');
    } else {
      this.showToast('Product not found', 'error');
    }
  }

  removeFromWishlist(productId: string): void {
    const user = this.authService.getCurrentUser();
    if (user) {
      this.wishlistItems = this.wishlistItems.filter(item => item.productId !== productId);
      this.filteredItems = this.filteredItems.filter(item => item.productId !== productId);
      
      const wishlistKey = `wishlist_${user.id}`;
      localStorage.setItem(wishlistKey, JSON.stringify(this.wishlistItems));
      
      this.showToast('Item removed from wishlist', 'success');
    }
  }

  clearWishlist(): void {
    const user = this.authService.getCurrentUser();
    if (user) {
      this.wishlistItems = [];
      this.filteredItems = [];
      
      const wishlistKey = `wishlist_${user.id}`;
      localStorage.setItem(wishlistKey, JSON.stringify([]));
      
      this.showToast('Wishlist cleared', 'info');
    }
  }

  private showToast(message: string, type: string = 'info'): void {
    // Toast implementation
    console.log(`${type}: ${message}`);
  }
}
